// 1. Take all 4 meetings coming from the Merge node
const meetings = $input.all().map(item => item.json);

// 2. Turn each meeting into readable text and join them,
//    putting a divider between meetings so the chain
//    knows where to cut later
const text = meetings
  .map(m => JSON.stringify(m, null, 2))
  .join('\n=====MEETING=====\n');

// 3. Output ONE item with everything inside a field called "text"
return [{ json: { text } }];
